const e = escapeHTML;
const paths = {
 cart:'M3 3h2l2 12h12l2-8H6M9 20h.01M18 20h.01', grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',
 box:'m3 7 9-4 9 4v10l-9 4-9-4zm0 0 9 4 9-4M12 11v10M7 5l10 4', receipt:'M5 3h14v18l-3-2-4 2-4-2-3 2zm4 5h6M9 12h6M9 16h3',
 chart:'M4 20V4M4 20h17M9 16v-4M14 16V8M19 16V5', users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M16 3a4 4 0 0 1 0 8M22 21v-2a4 4 0 0 0-3-3.9M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',
 shield:'m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6zm-4 9 3 3 5-6', settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M9 3h6l1 3 3 1 2 5-2 3-1 4-4 2-4-1-3-3-3-2-1-5 3-3z',
 search:'m21 21-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0', arrow:'M4 12h16m-6-6 6 6-6 6', plus:'M12 5v14M5 12h14', close:'m6 6 12 12M6 18 18 6',
 logout:'M9 4H4v16h5M9 12h12m-4-4 4 4-4 4', clock:'M12 8v4l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0', check:'m5 12 4 4L19 6',
 down:'m7 10 5 5 5-5', download:'M12 3v12m-5-5 5 5 5-5M5 17v4h14v-4', print:'M6 9V3h12v6M6 17H3V9h18v8h-3M6 14h12v7H6z',
 leaf:'M20 3c-9-2-17 2-16 9 1 6 8 7 12 3 4-4 4-12 4-12M4 21l11-11', cup:'M5 8h12v9c0 5-12 5-12 0zm12 1h3c3 0 3 6 0 6h-3M8 2v3M13 2v3',
 bag:'M5 7h14l2 14H3zm3 0V6a4 4 0 0 1 8 0v1', sun:'M12 2v2M12 20v2M2 12h2M20 12h2M5 5l1 1M18 18l1 1M5 19l1-1M18 6l1-1M17 12a5 5 0 1 1-10 0 5 5 0 0 1 10 0',
 edit:'m15 4 5 5M4 16 16 4a3 3 0 0 1 4 4L8 20H4z', image:'M3 3h18v18H3zm0 14 6-6 4 4 3-3 5 5M8 7h.01', refresh:'M20 7v5h-5M4 17v-5h5M5 7a8 8 0 0 1 14-2l1 2M4 17l1 2a8 8 0 0 0 14-2',
 laptop:'M4 3h16v13H4zM2 20l2-4h16l2 4z', dots:'M5 12h.01M12 12h.01M19 12h.01'
};
const icon = name => `<svg class="icon" aria-hidden="true" viewBox="0 0 24 24"><path d="${paths[name] || paths.box}"/></svg>`;
const money = n => new Intl.NumberFormat('en', {style:'currency', currency:S.bazaar?.currency_code || 'PHP'}).format((n||0)/100);
const num = n => new Intl.NumberFormat('en').format(n||0);
const timestamp = s => s ? new Date(s).toLocaleString('en', {timeZone:S.bazaar?.timezone || 'Asia/Manila', month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}) : '—';
const minor = value => {
  const s=String(value).trim();
  if(!/^\d{1,10}(\.\d{1,2})?$/.test(s)) throw new Error('Enter a positive amount with up to two decimal places.');
  const [a,b='']=s.split('.'); return Number(a)*100+Number(b.padEnd(2,'0'));
};
const key = () => [...crypto.getRandomValues(new Uint8Array(24))].map(n=>n.toString(16).padStart(2,'0')).join('');
const S={csrf:'',user:null,terminal:null,bazaar:null,day:null,shift:null,page:'checkout',products:[],categories:[],ticket:null,cart:[],search:'',category:'all',filters:{},online:true,paying:false,cartError:false};
let cartQueue=Promise.resolve(), currentReceipt=null, pollBusy=false, creatingTicket=null, cartPending=0;
async function api(path, method='GET', data, isForm=false){
  let response;
  try { response=await fetch('/api'+path,{method,credentials:'same-origin',headers:{...(method!=='GET'?{'X-CSRF-Token':S.csrf}:{}),...(!isForm&&data?{'Content-Type':'application/json'}:{})},body:data?(isForm?data:JSON.stringify(data)):undefined}); }
  catch{S.online=false;updateConnection();throw new Error('Connection lost. Reconnect and check the current ticket before retrying payment.');}
  S.online=true;updateConnection();
  let result;try{result=await response.json();}catch{result={error:'The server could not finish the request. Check the current ticket before retrying payment.'};}
  if(!response.ok){if(response.status===401&&S.user){S.user=null;renderAuth(false);}const error=new Error(result.error||'The request could not be completed.');error.status=response.status;throw error;}
  return result;
}
function toast(message,error=false){const t=$('#toast');t.textContent=message;t.className='show'+(error?' error':'');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.className='',6000);}
function updateConnection(){const node=$('#connection-state');if(node)node.innerHTML=`<span class="dot"></span>${S.online?'Local server connected':'Connection lost'}`;const banner=$('#connection-banner');if(banner){banner.hidden=S.online;banner.textContent='Connection lost. Checkout is paused. Reconnect to check your ticket.';}}
function button(label,action,style='light',i='',extra=''){return `<button type="button" class="btn ${style}" data-action="${action}" ${extra}>${i?icon(i):''}${label}</button>`;}
function field(label,name,type='text',value='',opts=''){return `<div class="field"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${e(value)}" ${opts}></div>`;}
function approval(){return `<div class="field full"><label for="f-manager_password">Confirm with your manager password</label><input id="f-manager_password" name="manager_password" type="password" autocomplete="current-password" required minlength="12"></div>`;}
function selectField(label,name,options,selected='',extra=''){return `<div class="field"><label for="f-${name}">${label}</label><select id="f-${name}" name="${name}" ${extra}>${options.map(([v,l])=>`<option value="${e(v)}" ${String(v)===String(selected)?'selected':''}>${e(l)}</option>`).join('')}</select></div>`;}
function empty(title,description,action='',label=''){return `<div class="empty">${icon('box')}<h3>${e(title)}</h3><p>${e(description)}</p>${action?button(label,action,'green','plus'):''}</div>`;}
function table(headers,rows){return `<div class="table-scroll"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`;}
function pill(text,style='success'){return `<span class="pill ${style}"><span class="dot"></span>${e(text)}</span>`;}
function heading(title,description,actions=''){return `<div class="page-heading"><div><div class="eyebrow">YOUR BAZAAR, IN ORDER</div><h1>${e(title)}</h1><p>${e(description)}</p></div><div class="actions">${actions}</div></div>`;}
function modal(title,body,wide=false){$('#modal-root').innerHTML=`<div class="modal-overlay"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><h2 id="modal-title">${e(title)}</h2><button class="icon-btn" aria-label="Close dialog" data-action="close-modal">${icon('close')}</button></div><div class="modal-body">${body}</div></section></div>`;setTimeout(()=>$('input:not([type=hidden]),select,button', $('.modal-body'))?.focus(),30);}
function closeModal(){if(S.paying)return;$('#modal-root').innerHTML='';currentReceipt=null;}
function formModal(title,body,onSubmit,submit='Save',wide=false){modal(title,`<form id="modal-form" class="form-grid">${body}<div class="form-error" role="alert"></div><div class="modal-actions">${button('Cancel','close-modal','light')}<button type="submit" class="btn green">${submit}${icon('arrow')}</button></div></form>`,wide);$('#modal-form').addEventListener('submit',async ev=>{ev.preventDefault();const form=ev.currentTarget;const submitButton=$('[type=submit]',form);submitButton.disabled=true;$('.form-error',form).textContent='';try{await onSubmit(Object.fromEntries(new FormData(form)),form);}catch(error){$('.form-error',form).textContent=error.message;}finally{submitButton.disabled=false;}});}
async function refreshState(){const data=await api('/state');Object.assign(S,data);return data;}
async function loadCatalog(){const data=await api('/catalog');S.products=data.products;S.categories=data.categories;}
function renderAuth(setup){
  $('#modal-root').innerHTML='';
  $('#app').innerHTML=`<div class="auth"><aside class="auth-story"><div class="brand"><img src="/static/mark.svg" alt=""><span>bazaar.</span></div><div class="auth-title"><div class="eyebrow">A LITTLE LESS ADMIN. A LITTLE MORE</div><h1>Room for<br>the <em>good stuff.</em></h1><p>Your products, your people, and every little sale. All together at one counter.</p></div><div class="auth-foot"><span class="dot"></span>Made for your local network. Ready without internet.</div><div class="auth-circle"></div></aside><main class="auth-form"><div class="eyebrow">${setup?'LET’S SET UP YOUR COUNTER':'WELCOME BACK'}</div><h2>${setup?'Make it your bazaar.':'Your counter is waiting.'}</h2><p>${setup?'Create the manager account on this host laptop. You can add your second cashier after setup.':'Sign in with your own account to open your shift.'}</p><form id="auth-form" class="form-grid">${setup?field('Your name','display_name','text','','required autocomplete="name"')+field('Bazaar name','bazaar_name','text','','required maxlength="120"'):''}${field('Username','username','text','','required autocomplete="username" minlength="3" maxlength="50"')}${field('Password','password','password','','required autocomplete="'+(setup?'new-password':'current-password')+'" '+(setup?'minlength="12"':''))}${setup?selectField('Currency','currency_code',[['PHP','PHP · Philippine peso'],['USD','USD · US dollar'],['TWD','TWD · Taiwan dollar'],['SGD','SGD · Singapore dollar'],['EUR','EUR · Euro'],['GBP','GBP · British pound'],['MYR','MYR · Malaysian ringgit'],['THB','THB · Thai baht'],['HKD','HKD · Hong Kong dollar'],['AUD','AUD · Australian dollar']],'PHP')+field('Bazaar timezone','timezone','text','Asia/Manila','required'):`<div class="field full"><label for="f-terminal_name">Laptop name</label><input id="f-terminal_name" name="terminal_name" value="Cashier laptop" required maxlength="80"><small>A manager approves each new laptop before it can use the counter.</small></div>`}<div class="form-error" role="alert"></div><div class="field full"><button class="btn green" type="submit">${setup?'Create my counter':'Sign in'}${icon('arrow')}</button></div></form><div class="auth-note">${setup?'Use at least 12 characters for your password. Currency and timezone apply to this bazaar.':'Each sale stays connected to the person who made it.'}</div></main></div>`;
  $('#auth-form').addEventListener('submit',async ev=>{ev.preventDefault();const form=ev.currentTarget;const b=$('[type=submit]',form);b.disabled=true;$('.form-error',form).textContent='';try{await api(setup?'/setup':'/login','POST',Object.fromEntries(new FormData(form)));await boot();}catch(error){$('.form-error',form).textContent=error.message;}finally{b.disabled=false;}});
}
function renderPending(){ $('#app').innerHTML=`<div class="auth"><aside class="auth-story"><div class="brand"><img src="/static/mark.svg" alt=""><span>bazaar.</span></div><div class="auth-title"><h1>A place at<br>the <em>counter.</em></h1></div></aside><main class="auth-form"><div class="eyebrow">LAPTOP APPROVAL</div><h2>One quick check.</h2><p>You’re signed in as ${e(S.user.display_name)}. Ask your manager to approve “${e(S.terminal.name)}” from Team & laptops on the host.</p>${button('Check approval','boot','green','refresh')} ${button('Sign out','logout','light')}</main></div>`;}
const nav=[['checkout','cart','Checkout'],['catalog','grid','Products'],['inventory','box','Inventory'],['transactions','receipt','Transactions'],['reports','chart','Reports'],['shifts','clock','Cashier shifts'],['team','users','Team & laptops'],['audit','shield','Audit trail'],['settings','settings','Settings']];
function shell(){
  const allowed=nav.filter(([id])=>S.user.role==='manager'||['checkout','transactions','shifts'].includes(id));
  const initials=S.user.display_name.split(' ').slice(0,2).map(w=>w[0]).join('').toUpperCase();
  $('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><img src="/static/mark.svg" alt=""><span>bazaar.</span><small>POS</small></div><div class="workspace"><span>${e(S.bazaar.name)}</span><small>LOCAL WORKSPACE · ${e(S.bazaar.currency_code)}</small></div><div class="nav-label">WORKSPACE</div><nav class="nav">${allowed.map(([id,i,label],index)=>`${index===5?'<div class="nav-gap"></div>':''}<button data-page="${id}" class="${S.page===id?'active':''}" title="${label}">${icon(i)}<span>${label}</span></button>`).join('')}</nav><div class="side-foot"><div class="local-status" id="connection-state"><span class="dot"></span>Local server connected</div><div class="side-user"><div class="avatar">${e(initials)}</div><div><strong>${e(S.user.display_name)}</strong><small>${e(S.user.role)} · ${e(S.terminal.name)}</small></div><button class="icon-btn" title="Sign out" aria-label="Sign out" data-action="logout">${icon('logout')}</button></div></div></aside><main class="main"><header class="topbar"><div class="breadcrumb">Workspace <span>/</span><b id="page-name">Checkout</b></div><div class="top-right"><span class="date-label">${new Intl.DateTimeFormat('en',{timeZone:S.bazaar.timezone,month:'short',day:'numeric',year:'numeric'}).format(new Date())}</span>${pill(S.day?'Day '+S.day.day_number+' is open':'Day closed',S.day?'success':'warn')}<div class="avatar">${e(initials)}</div></div></header><div id="connection-banner" class="connection-banner" hidden></div><div id="page" class="page"></div></main></div>`;
}
async function boot(){try{await cartQueue;await refreshState();if(!S.user)return renderAuth(S.setup_required);if(!S.terminal.approved)return renderPending();await loadCatalog();shell();await navigate(S.page);}catch(error){toast(error.message,true);if(!S.user)renderAuth(false);}}
async function navigate(page){
  S.page=page;$$('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$('#page-name').textContent=nav.find(n=>n[0]===page)?.[2]||page;
  const renderers={checkout:renderCheckout,catalog:renderCatalog,inventory:renderInventory,transactions:renderTransactions,reports:renderReports,shifts:renderShifts,team:renderTeam,audit:renderAudit,settings:renderSettings};
  try{await renderers[page]();}catch(error){toast(error.message,true);$('#page').innerHTML=empty('Unable to open this page',error.message);}
}
function gate(){
  if(!S.day)return `<div class="notice">${icon('sun')}<div><strong>A fresh day starts here.</strong><br>A manager needs to open the bazaar day before checkout.</div>${S.user.role==='manager'?`<div class="actions">${button('Open a day','open-day','green','plus')}</div>`:''}</div>`;
  if(!S.shift)return `<div class="notice">${icon('clock')}<div><strong>Ready for your first sale?</strong><br>Open your shift and record the cash in your drawer.</div><div class="actions">${button('Open my shift','open-shift','green','plus')}</div></div>`;
  return '';
}
async function renderCheckout(){
  await loadCatalog();
  let recoveredSale=null,pendingOpen=false;
  for(const storageKey of Object.keys(localStorage).filter(k=>k.startsWith(`bazaar-pending-${S.user.user_id}-`))){
    let body;try{body=JSON.parse(localStorage.getItem(storageKey));}catch{continue;}
    if(!Number.isInteger(body?.purchase_ticket_id))continue;
    const status=await api('/tickets/'+body.purchase_ticket_id);
    if(status.sale_id){recoveredSale=status.sale_id;localStorage.removeItem(storageKey);}
    else if(status.state==='open')pendingOpen=true;
    else localStorage.removeItem(storageKey);
  }
  const tickets=await api('/tickets');
  if(tickets.tickets.length){S.ticket=await api('/tickets/'+tickets.tickets[0].purchase_ticket_id);S.cart=S.ticket.lines.map(l=>({product_id:l.product_id,quantity:l.quantity}));}
  else{S.ticket=null;S.cart=[];}
  S.cartError=false;
  $('#page').innerHTML=heading('The counter','Good things, one sale at a time.',button('Refresh stock','refresh-catalog','light','refresh'))+gate()+`<div class="checkout-layout"><section class="shop-panel"><div class="search-row"><div class="search">${icon('search')}<input id="product-search" placeholder="Search products, SKU or scan barcode…" aria-label="Search products" value="${e(S.search)}" autocomplete="off"><kbd>/</kbd></div></div><div class="category-tabs" id="category-tabs"></div><div class="section-line"><strong>Browse products</strong><span id="product-count"></span></div><div class="product-grid" id="product-grid"></div><p class="stock-note">${icon('shield')}Stock is checked again when you complete the sale.</p></section><aside class="cart" id="cart"></aside></div>`;
  $('#product-search').addEventListener('input',ev=>{S.search=ev.target.value;renderProducts();});
  $('#product-search').addEventListener('keydown',ev=>{if(ev.key==='Enter'){ev.preventDefault();const matches=S.products.filter(p=>p.active&&(p.sku.toLowerCase()===S.search.toLowerCase()||p.barcode===S.search));if(matches.length===1)addProduct(matches[0].product_id).catch(err=>toast(err.message,true));}});
  renderCategories();renderProducts();renderCart();
  if(recoveredSale){await showReceipt(recoveredSale);toast('Recovered the saved payment. This is the original receipt.');}
  else if(pendingOpen)await paymentModal();
}
function renderCategories(){ $('#category-tabs').innerHTML=[['all','All products',S.products.filter(p=>p.active).length],...S.categories.filter(c=>c.active).map(c=>[c.category_id,c.name,S.products.filter(p=>p.active&&p.category_id===c.category_id).length])].map(([id,label,count])=>`<button data-category="${id}" class="${String(S.category)===String(id)?'active':''}">${e(label)}<span>${count}</span></button>`).join(''); }
const tileColors=['#f0eee3','#e9eee2','#efebe5','#e6edeb','#eee6e0','#eae8f1'];
function productVisual(p){return p.product_image_id?`<img src="/api/images/${p.product_image_id}" alt="${e(p.description)}" loading="lazy">`:icon(['bag','cup','leaf','box'][p.category_id%4]);}
function renderProducts(){
  const search=S.search.toLowerCase();const products=S.products.filter(p=>p.active&&(S.category==='all'||String(p.category_id)===String(S.category))&&[p.sku,p.description,p.barcode||''].some(v=>v.toLowerCase().includes(search)));
  $('#product-count').textContent=`${products.length} products`;
  $('#product-grid').innerHTML=products.map(p=>`<button class="product-card ${p.quantity_on_hand===0?'sold-out':''}" data-add="${p.product_id}" ${!p.quantity_on_hand?'disabled':''} aria-label="Add ${e(p.description)}"><div class="product-visual" style="--tile:${tileColors[p.category_id%tileColors.length]}">${productVisual(p)}<span class="stock-badge ${p.quantity_on_hand<6?'low':''}">${p.quantity_on_hand?p.quantity_on_hand+' in stock':'Out of stock'}</span></div><div class="product-detail"><div class="eyebrow">${e(p.category_name)}</div><h3>${e(p.description)}</h3><div class="product-bottom"><strong>${money(p.amount_minor)} <small>/ ${e(p.unit)}</small></strong><span class="add-badge">+</span></div></div></button>`).join('')||`<div class="no-results">${empty(S.products.length?'No products found':'Your shelves are ready',S.products.length?'Try another name, SKU, or category.':'Add your products and opening stock to get started.',S.user.role==='manager'?'new-product':'', 'Add a product')}</div>`;
}
function cartTotal(){return S.cart.reduce((total,l)=>total+(S.products.find(p=>p.product_id===l.product_id)?.amount_minor||0)*l.quantity,0);}
function renderCart(){
  if(!$('#cart'))return;const units=S.cart.reduce((a,l)=>a+l.quantity,0);
  $('#cart').innerHTML=`<div class="cart-header"><h2>Current order <span class="count-bubble">${units}</span></h2><button class="icon-btn" data-action="cancel-ticket" title="Cancel order" aria-label="Cancel order" ${!S.ticket?'disabled':''}>${icon('close')}</button></div><div class="cart-ticket"><span>${S.ticket?e(S.ticket.ticket_number):'A new order awaits'}</span><span>${e(S.user.display_name.split(' ')[0])}</span></div><div class="cart-lines">${S.cart.length?S.cart.map(l=>{const p=S.products.find(p=>p.product_id===l.product_id);if(!p)return '';return `<div class="cart-line"><div class="cart-thumb">${productVisual(p)}</div><div><h3>${e(p.description)}</h3><small>${money(p.amount_minor)} / ${e(p.unit)}</small><div class="qty-control"><button data-qty="${p.product_id}" data-delta="-1" aria-label="Remove one ${e(p.description)}">−</button><span>${l.quantity}</span><button data-qty="${p.product_id}" data-delta="1" aria-label="Add one ${e(p.description)}">+</button></div></div><strong>${money(p.amount_minor*l.quantity)}</strong></div>`;}).join(''):`<div class="cart-empty">${icon('cart')}<p>A little empty for now.<br>Choose a product to start an order.</p></div>`}</div><div class="cart-summary"><div class="sum-row"><span>Subtotal</span><span>${money(cartTotal())}</span></div><div class="sum-row"><span>Items</span><span>${units} ${units===1?'item':'items'}</span></div><div class="sum-row total"><span>Total amount</span><strong>${money(cartTotal())}</strong></div>${button('Review payment','pay','green','arrow',!S.cart.length||!S.shift||S.cartError?'disabled':'')}</div><div class="cart-foot">${S.cartError?'Cart needs a refresh before payment':S.ticket?'Saved to this ticket · Cash payment':'One ticket. One payment. One receipt.'}</div>`;
  if(S.ticket){const transfer=document.createElement('button');transfer.type='button';transfer.className='icon-btn';transfer.dataset.action='transfer-ticket';transfer.setAttribute('aria-label','Transfer this order');transfer.title='Transfer this order';transfer.innerHTML=icon('users');$('.cart-ticket').appendChild(transfer);}
  if(cartPending){$('.cart-foot').textContent='Saving this ticket…';$('[data-action=pay]').disabled=true;}
}
async function addProduct(pid,delta=1){
  if(!S.day||!S.shift)throw new Error('Open the bazaar day and your shift before starting a sale.');
  if(!S.ticket){if(!creatingTicket)creatingTicket=api('/tickets','POST',{}).then(t=>{S.ticket=t;S.cart=t.lines.map(l=>({product_id:l.product_id,quantity:l.quantity}));}).finally(()=>creatingTicket=null);await creatingTicket;}
  if(localStorage.getItem(`bazaar-pending-${S.user.user_id}-${S.ticket.purchase_ticket_id}`))throw new Error('Review the previous payment result before changing this order.');
  const p=S.products.find(p=>p.product_id===pid);const existing=S.cart.find(l=>l.product_id===pid);const qty=(existing?.quantity||0)+delta;
  if(qty>p.quantity_on_hand)throw new Error('That quantity exceeds the stock currently available.');
  if(qty<=0)S.cart=S.cart.filter(l=>l.product_id!==pid);else if(existing)existing.quantity=qty;else S.cart.push({product_id:pid,quantity:qty});
  const snapshot=S.cart.map(l=>({...l}));cartPending++;renderCart();
  cartQueue=cartQueue.then(async()=>{try{if(!S.cartError)S.ticket=await api('/tickets/'+S.ticket.purchase_ticket_id,'PUT',{version:S.ticket.version,lines:snapshot});}catch(error){S.cartError=true;toast(error.message+' Refresh the counter to recover the saved cart.',true);}finally{cartPending--;renderCart();}});
  await cartQueue;
}
async function paymentModal(){
  await cartQueue;if(S.cartError)throw new Error('Refresh the counter to recover the saved cart.');
  const q=await api('/tickets/'+S.ticket.purchase_ticket_id);S.ticket=q;
  if(q.sale_id){await showReceipt(q.sale_id);return;}
  requireClient(q.lines.length,'Add an item first.');
  const pendingKey=`bazaar-pending-${S.user.user_id}-${q.purchase_ticket_id}`;
  let pending;try{pending=JSON.parse(localStorage.getItem(pendingKey)||'null');}catch{pending=null;}
  const total=q.total_minor;
  modal('Complete this order',`<form id="payment-form" class="form-grid"><div class="payment-total field full"><small>${e(q.ticket_number)} · ${q.lines.reduce((a,l)=>a+l.quantity,0)} items</small><strong>${money(total)}</strong><small>Cash payment · No discount or tax applied</small></div><div class="field full"><label for="amount-paid">Amount paid</label><input id="amount-paid" name="amount" type="text" inputmode="decimal" placeholder="0.00" value="${pending?(pending.tendered_minor/100).toFixed(2):''}" required autocomplete="off" ${pending?'readonly':''}></div><div class="quick-cash">${[total,...[10000,20000,50000,100000].filter(n=>n>total).slice(0,3)].map(n=>`<button type="button" data-cash="${n}" ${pending?'disabled':''}>${n===total?'Exact':money(n)}</button>`).join('')}</div><div class="change-line"><span>Change due</span><strong id="change-due">${money(pending?pending.tendered_minor-total:0)}</strong></div><div class="form-error" role="alert"></div><div class="field full"><small>${pending?'This payment was submitted before. Retrying will retrieve the same sale if it was saved.':'Check the amount before confirming. A receipt follows the saved sale.'}</small></div><div class="modal-actions">${button('Back','close-modal','light')}<button type="submit" class="btn green">${pending?'Check / retry payment':'Confirm payment'}${icon('check')}</button></div></form>`);
  if(q.duplicate_warning){const warning=document.createElement('div');warning.className='notice field full';warning.innerHTML=`<label class="check-field"><input id="duplicate-reviewed" type="checkbox" required ${pending?.duplicate_reviewed?'checked':''}><span>A matching order (${e(q.duplicate_warning.receipt_number)}) was saved in the last two minutes. I checked that this is a separate customer purchase.</span></label>`;$('#payment-form').prepend(warning);}
  $('#amount-paid').addEventListener('input',()=>{try{$('#change-due').textContent=money(Math.max(0,minor($('#amount-paid').value)-total));}catch{$('#change-due').textContent='—';}});
  $('#payment-form').addEventListener('submit',async ev=>{
    ev.preventDefault();const form=ev.currentTarget,b=$('[type=submit]',form);b.disabled=true;$('.form-error',form).textContent='';
    try{
      const amount=minor($('#amount-paid').value);requireClient(amount>=total,'The amount paid is less than the total.');
      const body=pending||{request_key:key(),purchase_ticket_id:q.purchase_ticket_id,version:q.version,quote_hash:q.quote_hash,tendered_minor:amount,duplicate_reviewed:!!$('#duplicate-reviewed')?.checked};
      localStorage.setItem(pendingKey,JSON.stringify(body));pending=body;S.paying=true;
      const result=await api('/checkout','POST',body);localStorage.removeItem(pendingKey);S.paying=false;S.ticket=null;S.cart=[];
      await renderCheckout();await showReceipt(result.sale_id);toast(result.replayed?'Retrieved the existing sale.':'Payment saved. The order is complete.');
    }catch(error){
      S.paying=false;
      if(pending&&[400,403,409,429].includes(error.status)){
        localStorage.removeItem(pendingKey);pending=null;closeModal();await renderCheckout();toast(error.message+' Review the order before paying.',true);
      }else{
        $('.form-error',form).textContent=error.message;if($('#amount-paid'))$('#amount-paid').readOnly=!!pending;
      }
    }finally{b.disabled=false;}
  });
}
function requireClient(condition,message){if(!condition)throw new Error(message);}
async function showReceipt(sid){
  const r=await api('/sales/'+sid);currentReceipt=r;const s=r.sale,p=r.payment;
  modal('Acknowledgement receipt',`<div class="receipt-content"><h2>${e(s.bazaar_name)}</h2><p>ACKNOWLEDGEMENT RECEIPT</p><p>${e(s.receipt_number)}</p><div class="receipt-meta">Day ${s.day_number} · ${e(s.business_date)}<br>${e(timestamp(s.completed_at))}<br>Cashier: ${e(s.display_name)}</div><table><thead><tr><th>ITEM</th><th class="right">AMOUNT</th></tr></thead><tbody>${r.lines.map(l=>`<tr><td>${e(l.description_snapshot)}<br>${l.quantity} × ${money(l.unit_price_minor)}</td><td class="right">${money(l.line_total_minor)}</td></tr>`).join('')}</tbody></table><div class="sum-row total"><span>TOTAL</span><strong>${money(s.total_minor)}</strong></div><div class="sum-row"><span>Cash paid</span><span>${money(p.tendered_minor)}</span></div><div class="sum-row"><span>Change</span><span>${money(p.change_minor)}</span></div><div class="receipt-thanks">Thank you for stopping by.<br>Every little purchase means a lot.</div></div>${r.corrections.length?`<div class="receipt-extra notice">${r.corrections.length} correction(s) linked · ${money(r.corrections.reduce((a,c)=>a+c.refund_total_minor,0))} refunded</div>`:''}<div class="modal-actions">${S.user.role==='manager'?button('Return / void','return-sale','light','refresh',`data-id="${sid}"`):''}${button('Print / save PDF','print-receipt','green','print',`data-id="${sid}"`)}</div>`);currentReceipt=r;
}
function openDay(){const today=new Intl.DateTimeFormat('en-CA',{timeZone:S.bazaar.timezone,year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());formModal('Open the next bazaar day',field('Business date','business_date','date',today,'required')+approval(),async data=>{await api('/days/open','POST',data);closeModal();await boot();toast('The bazaar day is open.');},'Open day');}
function openShift(){formModal('Open your cashier shift',`<div class="field full"><small>Count the starting cash in this laptop’s drawer. Sales and refunds will be reconciled against it.</small></div>`+field('Opening cash','opening_cash','text','0.00','required inputmode="decimal"'),async data=>{await api('/shifts/open','POST',{opening_cash_minor:minor(data.opening_cash)});closeModal();await boot();toast('Your shift is open.');},'Open shift');}
async function cancelTicket(){await cartQueue;if(!S.ticket)return;formModal('Cancel this order',`<div class="field full"><small>This cancels the open ticket. Completed sales use a manager-approved correction.</small></div>`+field('Reason','reason','text','','required'),async data=>{await api('/tickets/'+S.ticket.purchase_ticket_id+'/cancel','POST',{reason:data.reason,version:S.ticket.version});closeModal();S.ticket=null;S.cart=[];await renderCheckout();toast('Order cancelled.');},'Cancel order');}
